import{_ as t,o as h,c as o,a3 as c}from"./chunks/framework.DX_KL3e0.js";const g="/help/screenshots/quan-tri/cau-hinh-cham-cong.png",d=JSON.parse('{"title":"Cấu hình Chấm công","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/cau-hinh-cham-cong.md","filePath":"quan-tri/cau-hinh-cham-cong.md","lastUpdated":1783009205000}'),a={name:"quan-tri/cau-hinh-cham-cong.md"};function i(r,n,s,l,u,e){return h(),o("div",null,[...n[0]||(n[0]=[c('<h1 id="cau-hinh-cham-cong" tabindex="-1">Cấu hình Chấm công <a class="header-anchor" href="#cau-hinh-cham-cong" aria-label="Permalink to &quot;Cấu hình Chấm công&quot;">​</a></h1><p>Khu vực cấu hình của module Chấm công gồm <strong>2 phần</strong>: quản lý <strong>máy chấm công</strong> và cấu hình <strong>loại phép &amp; chính sách phép năm</strong>.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Máy chấm công:</strong> <code>/tra-cuu/du-lieu-cong/cau-hinh</code> (quyền <code>cham-cong-machines</code>).</li><li><strong>Loại phép:</strong> <code>/tra-cuu/du-lieu-cong/nghi-phep/cau-hinh</code> (quyền <code>cham-cong-leave-config</code>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin (theo phân quyền module con của Chấm công).</li></ul></div><h2 id="cau-hinh-may-cham-cong" tabindex="-1">Cấu hình máy chấm công <a class="header-anchor" href="#cau-hinh-may-cham-cong" aria-label="Permalink to &quot;Cấu hình máy chấm công&quot;">​</a></h2><p>Trang <strong>Quản lý máy chấm công</strong> dùng để thêm, sửa và kiểm tra kết nối với máy chấm công (ZKTeco / Ronald Jack).</p><p><img src="'+g+'" alt="Trang Cấu hình Chấm công"></p><h3 id="hai-che-đo-ket-noi" tabindex="-1">Hai chế độ kết nối <a class="header-anchor" href="#hai-che-đo-ket-noi" aria-label="Permalink to &quot;Hai chế độ kết nối&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chế độ</th><th>Cách hoạt động</th></tr></thead><tbody><tr><td><strong>Pull</strong></td><td>Hệ thống chủ động kết nối tới IP/cổng của máy để lấy dữ liệu. Hỗ trợ <strong>kiểm tra kết nối</strong> trước khi lưu.</td></tr><tr><td><strong>Push (ADMS)</strong></td><td>Máy tự <strong>gửi</strong> dữ liệu về server qua giao thức ADMS — không cần mở cổng vào, an toàn khi kết nối qua domain.</td></tr></tbody></table><h3 id="them-may-che-đo-pull" tabindex="-1">Thêm máy (chế độ Pull) <a class="header-anchor" href="#them-may-che-đo-pull" aria-label="Permalink to &quot;Thêm máy (chế độ Pull)&quot;">​</a></h3><ol><li>Nhấn <strong>Thêm</strong> trên danh sách máy.</li><li>Nhập <strong>mã máy</strong>, <strong>tên</strong> (vd: <em>Ronald Jack - VP A</em>).</li><li>Chọn chế độ <strong>Pull</strong>.</li><li>Nhập <strong>IP / Domain</strong> và <strong>cổng</strong> (port).</li><li>Chọn hãng (vd <strong>ZKTeco</strong>), nhập <strong>khóa giao tiếp</strong>, vị trí lắp đặt.</li><li>Nhấn <strong>Kiểm tra kết nối</strong> để xác nhận, rồi <strong>Lưu</strong>.</li></ol><h3 id="them-may-che-đo-push-adms" tabindex="-1">Thêm máy (chế độ Push / ADMS) <a class="header-anchor" href="#them-may-che-đo-push-adms" aria-label="Permalink to &quot;Thêm máy (chế độ Push / ADMS)&quot;">​</a></h3><ol><li>Chọn chế độ <strong>Push (ADMS)</strong>.</li><li>Trên <strong>máy chấm công</strong>, khai báo Server theo hướng dẫn hiển thị trên màn hình (domain + Port 443, bật HTTPS).</li><li>Nhập thông tin tham chiếu (host) rồi <strong>Lưu</strong>; máy sẽ tự gửi dữ liệu lên.</li></ol><p>Chi tiết kết nối phần cứng và xử lý sự cố máy chấm công: liên hệ IT.</p><h2 id="quy-tac-cham-cong-theo-cong-ty-theo-ngay-hieu-luc" tabindex="-1">Quy Tắc Chấm Công (theo công ty, theo ngày hiệu lực) <a class="header-anchor" href="#quy-tac-cham-cong-theo-cong-ty-theo-ngay-hieu-luc" aria-label="Permalink to &quot;Quy Tắc Chấm Công (theo công ty, theo ngày hiệu lực)&quot;">​</a></h2><p>Ngay trong trang <strong>Cấu Hình Máy Chấm Công</strong>, Super Admin có khối <strong>Quy Tắc Chấm Công</strong> để tùy chỉnh giờ làm, kỳ công, deadline, khung tăng ca… <strong>theo từng công ty</strong>. Mỗi lần lưu tạo một <strong>phiên bản có hiệu lực từ ngày chỉ định</strong> — không ảnh hưởng số liệu kỳ đã chốt.</p><div class="info custom-block"><p class="custom-block-title">Chọn phạm vi</p><p>Ở đầu khối, chọn <strong>Phạm vi áp dụng</strong>: <em>Mặc định toàn hệ thống</em> (fallback khi công ty chưa có riêng) hoặc một công ty cụ thể.</p></div><h3 id="cac-nhom-cau-hinh" tabindex="-1">Các nhóm cấu hình <a class="header-anchor" href="#cac-nhom-cau-hinh" aria-label="Permalink to &quot;Các nhóm cấu hình&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nhóm</th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Kỳ công</strong></td><td>Ngày bắt đầu / kết thúc kỳ (theo tháng dương lịch hoặc cross-month, vd 28→27).</td></tr><tr><td><strong>Giờ làm &amp; nghỉ trưa</strong></td><td>Giờ nghỉ trưa, ngưỡng đủ 1 ngày công (phút).</td></tr><tr><td><strong>Khung phân loại lượt chấm</strong></td><td>Khung giờ nhận diện Vào / Ra.</td></tr><tr><td><strong>Deadline &amp; quy tắc bù công</strong></td><td>Hạn gửi Bù Công/Bù Giờ · <strong>Thời gian tự gửi Bảng Công</strong> · giờ sớm nhất gửi bù công trong ngày.</td></tr><tr><td><strong>🆕 Giờ làm trong tuần</strong></td><td>Bật/tắt ngày làm và đặt <strong>giờ vào–ra riêng cho từng thứ</strong> (T2…CN). Ngày tắt = nghỉ.</td></tr><tr><td><strong>🆕 Khung buổi sáng / chiều</strong></td><td>Khung giờ sáng &amp; chiều — dùng cho nghỉ phép nửa buổi.</td></tr><tr><td><strong>Khung tăng ca</strong></td><td>Khung tối / đêm (giờ VN).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">🆕 Giờ làm theo từng thứ (thay &quot;Ngày nghỉ trong tuần&quot;)</p><p>Trước đây chỉ đánh dấu ngày nghỉ. Nay đặt được <strong>giờ vào–ra riêng cho từng thứ</strong> — ví dụ T2–T6 làm 08:00–17:00, T7 làm 07:00–11:00, CN nghỉ. Nhờ đó <strong>đi trễ / về sớm</strong> trong Hồ Sơ Chuyên Cần tính đúng theo ca thực của từng ngày.</p></div><div class="tip custom-block"><p class="custom-block-title">🆕 Thời gian tự gửi Bảng Công &amp; &quot;tháng kế tiếp&quot;</p><p>Đây là mốc hệ thống <strong>tự chốt &amp; gửi</strong> bảng công của kỳ. Nếu công ty tính kỳ theo <strong>tháng dương lịch</strong> (vd 01–30/06) và muốn hạn rơi vào <strong>ngày đầu tháng sau</strong> (01/07), tick ô <strong>&quot;Mốc rơi vào tháng kế tiếp của kỳ&quot;</strong> rồi đặt Ngày = 1. Cùng cơ chế cho <strong>Hạn gửi Bù Công</strong>.</p></div><h3 id="luu-sua-xoa-phien-ban" tabindex="-1">Lưu, sửa &amp; xoá phiên bản <a class="header-anchor" href="#luu-sua-xoa-phien-ban" aria-label="Permalink to &quot;Lưu, sửa &amp; xoá phiên bản&quot;">​</a></h3><ol><li>Ở khối <strong>Tạo / cập nhật phiên bản cấu hình</strong>, chọn <strong>Ngày hiệu lực</strong> (nên là ngày bắt đầu kỳ công), chỉnh các nhóm rồi bấm <strong>Lưu phiên bản</strong>.</li><li>Danh sách <strong>Phiên bản đã lưu</strong> hiển thị theo ngày hiệu lực. Mỗi phiên bản có: <ul><li>🆕 Nút <strong>Sửa</strong> — nạp lại cấu hình + ngày hiệu lực + ghi chú vào form; lưu lại cùng ngày hiệu lực sẽ <strong>ghi đè</strong> phiên bản đó.</li><li>Nút <strong>Xoá</strong> — hệ thống dùng phiên bản hiệu lực trước đó (hoặc mặc định).</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">Không tính lại kỳ đã chốt</p><p>Cấu hình chỉ áp dụng cho kỳ công có ngày làm ≥ ngày hiệu lực. Bảng công đã gửi/chốt không bị tính lại.</p></div><h2 id="cau-hinh-loai-phep-chinh-sach" tabindex="-1">Cấu hình loại phép &amp; chính sách <a class="header-anchor" href="#cau-hinh-loai-phep-chinh-sach" aria-label="Permalink to &quot;Cấu hình loại phép &amp; chính sách&quot;">​</a></h2><p>Trang <strong>Cấu Hình Nghỉ Phép</strong> (<code>/tra-cuu/du-lieu-cong/nghi-phep/cau-hinh</code>) gồm <strong>3 tab</strong>:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Loại Phép</strong></td><td>Khai báo các loại nghỉ phép (phép năm, không lương, ốm...).</td></tr><tr><td><strong>Chính Sách</strong></td><td>Quy tắc cấp phép năm, mức cộng dồn, ngày tối đa...</td></tr><tr><td><strong>Số Dư</strong></td><td>Theo dõi/điều chỉnh số dư phép của nhân viên.</td></tr></tbody></table><h3 id="them-loai-phep" tabindex="-1">Thêm loại phép <a class="header-anchor" href="#them-loai-phep" aria-label="Permalink to &quot;Thêm loại phép&quot;">​</a></h3><ol><li>Mở tab <strong>Loại Phép</strong>, nhấn <strong>Thêm</strong>.</li><li>Nhập tên loại phép và thuộc tính liên quan (có trừ lương, có giới hạn...).</li><li><strong>Lưu</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Liên quan đến duyệt</p><p>Loại phép &amp; chính sách cấu hình ở đây áp dụng cho luồng xin nghỉ và bảng công. Việc duyệt bù công/tăng ca xem <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a>.</p></div><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a></p>',31)])])}const p=t(a,[["render",i]]);export{d as __pageData,p as default};
